# 사막 필드 + 피라미드·고분 조각 메타 — 굽는 스크립트가 읽는다(partmeta.json). 키 = 함수 이름(파일 이름은 _ → -).
def M(kind, ko, desc, rules, brows=None, layer=None, role=None, mod='P'):
    d = dict(kind=kind, ko=ko, desc=desc, rules=rules, mod=mod)
    if brows is not None: d['brows'] = brows
    if layer: d['layer'] = layer
    if role: d['role'] = role
    return d

